//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-replace-children.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}


#[test]
fn noscript_replace_children_single_actual_text_moves_source_and_combined_record_and_ranges(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),old=host.firstChild,out=document.getElementById('out'),a=document.createTextNode('A\udfff\ud800B'),range=document.createRange(),incoming=document.createRange(),watch=new MutationObserver(function(){});out.appendChild(a);range.setStart(old,1);range.setEnd(old,3);incoming.setStart(a,1);incoming.setEnd(a,3);watch.observe(out,{childList:true});watch.observe(host,{childList:true});if(host.replaceChildren(a)!==undefined)throw 'replaceChildren return';var rs=watch.takeRecords();if(host.firstChild!==a||host.childNodes.length!==1||a.parentNode!==host||a.ownerDocument!==document||a.data!=='A\udfff\ud800B'||host.innerHTML!==a.data||old.parentNode!==null||old.data!=='held'||out.textContent!=='Real'||rs.length!==2||rs[0].target!==out||rs[0].removedNodes[0]!==a||rs[1].target!==host||rs[1].removedNodes[0]!==old||rs[1].addedNodes[0]!==a||rs[1].previousSibling!==null||rs[1].nextSibling!==null||range.startContainer!==host||range.endContainer!==host||range.startOffset||range.endOffset||incoming.startContainer!==out||incoming.endContainer!==out||incoming.startOffset!==1||incoming.endOffset!==1)throw 'actual single passive replace-all';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_replace_children_multiple_exact_text_self_reuse_and_empty_clear_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),old=host.firstChild,a=document.createTextNode('<b>literal</b>'),b=document.createTextNode('tail'),watch=new MutationObserver(function(){});watch.observe(host,{childList:true});host.replaceChildren(a,'\udfff','\ud800',b);var rs=watch.takeRecords(),low=a.nextSibling,high=low.nextSibling;if(host.childNodes.length!==4||host.firstChild!==a||host.lastChild!==b||low.nodeType!==3||high.nodeType!==3||low.data!=='\udfff'||high.data!=='\ud800'||low.ownerDocument!==document||high.ownerDocument!==document||high.nextSibling!==b||old.parentNode!==null||old.data!=='held'||rs.length!==1||rs[0].target!==host||rs[0].removedNodes[0]!==old||rs[0].addedNodes.length!==4||rs[0].addedNodes[0]!==a||rs[0].addedNodes[1]!==low||rs[0].addedNodes[2]!==high||rs[0].addedNodes[3]!==b)throw 'actual variadic passive Text replacement';host.replaceChildren(a);rs=watch.takeRecords();if(host.firstChild!==a||host.childNodes.length!==1||a.parentNode!==host||low.parentNode!==null||high.parentNode!==null||b.parentNode!==null||rs.length!==1||rs[0].removedNodes.length!==4||rs[0].removedNodes[0]!==a||rs[0].addedNodes[0]!==a)throw 'same actual Text reuse';host.replaceChildren();rs=watch.takeRecords();if(host.firstChild!==null||a.parentNode!==null||a.data!=='<b>literal</b>'||rs.length!==1||rs[0].removedNodes[0]!==a||rs[0].addedNodes.length)throw 'actual empty replace-all';host.replaceChildren();if(watch.takeRecords().length)throw 'empty no-op records';host.replaceChildren('fresh');rs=watch.takeRecords();if(host.firstChild.data!=='fresh'||host.firstChild.nodeType!==3||rs.length!==1||rs[0].addedNodes[0]!==host.firstChild||rs[0].removedNodes.length||document.querySelectorAll('b').length)throw 'fresh empty-host replacement';"#);assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_replace_children_nontext_and_native_source_destination_guards_preserve_both_trees(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,guarded=document.getElementById('guard'),blocked=guarded.firstChild,span=document.createElement('span'),fresh=document.createTextNode('fresh'),mixed=document.createDocumentFragment(),watch=new MutationObserver(function(){});mixed.appendChild(document.createTextNode('prefix'));mixed.appendChild(span);watch.observe(document.body,{childList:true,subtree:true});watch.observe(mixed,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 for code in ["host.replaceChildren(mixed);","host.replaceChildren(span);","host.replaceChildren(blocked);","guarded.replaceChildren(fresh);"]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(e.contains("inert resource subtrees"),"{code}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==old||guarded.firstChild!==blocked||mixed.childNodes.length!==2||span.parentNode!==mixed||fresh.parentNode!==null||watch.takeRecords().length)throw 'replace-all protected prefix';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_replace_children_copy_work_retained_refusals_preserve_donor_and_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,donor=document.createDocumentFragment();for(var i=0;i<128;i++)donor.appendChild(document.createTextNode('x'));var text=donor.firstChild,watch=new MutationObserver(function(){}),range=document.createRange();range.setStart(text,0);range.setEnd(text,1);watch.observe(donor,{childList:true});watch.observe(host,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let e=refusal(&mut d,&mut f,&mut p,"host.replaceChildren(donor);").to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==old||old.parentNode!==host||donor.childNodes.length!==128||donor.firstChild!==text||text.parentNode!==donor||range.startContainer!==text||range.endContainer!==text||range.startOffset||range.endOffset!==1||watch.takeRecords().length)throw 'replace-all quota atomic';");}p.begin_job();run(&mut d,&mut f,&mut p,"host.replaceChildren(donor);var rs=watch.takeRecords();if(host.childNodes.length!==128||host.firstChild!==text||old.parentNode!==null||old.data!=='held'||donor.firstChild!==null||rs.length!==2||rs[0].target!==donor||rs[0].removedNodes.length!==128||rs[1].target!==host||rs[1].removedNodes[0]!==old||rs[1].addedNodes.length!==128||range.startContainer!==donor||range.endContainer!==donor||range.startOffset||range.endOffset)throw 'fresh passive replace-all recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
